        _log.CombatAnchors[0].SystemName.Should().Be("Jita");
    }

    [Fact]
    public void MarkCombat_InvalidSystemId_Ignored()
    {
        _log.MarkCombat(0, "Nowhere");
        _log.MarkCombat(-1, "Negative");

        _log.HasBattleReport.Should().BeFalse();
    }

